# Patch vertical mode and inspect any invalid mappings.
def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    hr=next(r for r in range(h) if all(v==1 for v in grid[r]))
    vc=next(c for c in range(w) if all(grid[r][c]==1 for r in range(h)))
    def red_bbox(r0,r1,c0,c1):
        cells=[(r,c) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c]==2]
        rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
        return min(rs),max(rs)+1,min(cs),max(cs)+1
    def components(r0,r1,c0,c1,source):
        seen=set(); comps=[]
        for r in range(r0,r1):
            for c in range(c0,c1):
                if (r,c) in seen or source[r][c] in (4,2): continue
                color=source[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if r0<=x<r1 and c0<=y<c1 and (x,y) not in seen and source[x][y]==color:
                            seen.add((x,y)); stack.append((x,y))
                comps.append((color,cells))
        return comps
    def transfer(sr_bounds,tr_bounds,source,mode):
        sr0,sr1,sc0,sc1=red_bbox(*sr_bounds)
        tr0,tr1,tc0,tc1=red_bbox(*tr_bounds)
        sy=(tr1-tr0)/(sr1-sr0); sx=(tc1-tc0)/(sc1-sc0)
        for color,cells in components(*sr_bounds,source):
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            a,b=min(rs),max(rs)+1; c,d=min(cs),max(cs)+1
            if mode=='vertical':
                na=round(tr0+((sr1-sr0)-(b-sr0))*sy); nb=round(tr0+((sr1-sr0)-(a-sr0))*sy)
            else:
                na=round(tr0+(a-sr0)*sy); nb=round(tr0+(b-sr0)*sy)
            if mode=='horizontal':
                nc=round(tc0+((sc1-sc0)-(d-sc0))*sx); nd=round(tc0+((sc1-sc0)-(c-sc0))*sx)
            else:
                nc=round(tc0+(c-sc0)*sx); nd=round(tc0+(d-sc0)*sx)
            for rr in range(na,nb):
                for cc in range(nc,nd): out[rr][cc]=color
    tl=(0,hr,0,vc); bl=(hr+1,h,0,vc); tr=(0,hr,vc+1,w); br=(hr+1,h,vc+1,w)
    transfer(tl,bl,grid,'vertical')
    transfer(tl,tr,grid,'horizontal')
    transfer(bl,br,out,'horizontal')
    return out
